141	///|
142	fn add_protected_secret(secrets : Array[String], value : String) -> Unit {
143	  if value == "" {
144	    return
145	  }
146	  let values = [value]
147	  for part in value.split("\n") {
148	    if part.trim() != "" && part.length() < value.length() {
149	      values.push(part.to_owned())
150	    }
151	  }
152	  for item in values {
153	    if !secrets.contains(item) {
154	      secrets.push(item)
155	    }
156	    let encoded = Json::string(item).stringify()
157	    let escaped = encoded[1:encoded.length() - 1].to_owned()
158	    if escaped != item && !secrets.contains(escaped) {
159	      secrets.push(escaped)
160	    }
161	  }
162	}
