1100	      incomplete = true
1101	      line[:1024].to_owned()
1102	    } else {
1103	      line.to_owned()
1104	    }
1105	    let bounded = if truncated ||
1106	      (incomplete_final_line && index == source_lines.length() - 1) {
1107	      diagnostic_partial_secret(bounded, progress.secrets)
1108	    } else {
1109	      bounded
1110	    }
1111	    match progress.safe_message(bounded) {
1112	      Some(safe) => lines.push(safe)
1113	      None => {
1114	        incomplete = true
1115	        lines.push("[unavailable]")
1116	      }
1117	    }
1118	  }
