1126	///|
1127	fn diagnostic_partial_secret(text : String, secrets : Array[String]) -> String {
1128	  let chars = text.iter().to_array()
1129	  let mut boundary = chars.length()
1130	  for secret in secrets {
1131	    let value = secret.iter().to_array()
1132	    if value.length() == 0 || text.has_suffix(secret) {
1133	      continue
1134	    }
1135	    let limit = if value.length() - 1 < boundary {
1136	      value.length() - 1
1137	    } else {
1138	      boundary
1139	    }
1140	    if limit == 0 {
1141	      continue
1142	    }
1143	    let prefixes = FixedArray::make(limit, 0)
1144	    let mut matched = 0
1145	    for index in 1..<limit {
1146	      while matched > 0 && value[matched] != value[index] {
1147	        matched = prefixes[matched - 1]
1148	      }
1149	      if value[matched] == value[index] {
1150	        matched += 1
1151	      }
1152	      prefixes[index] = matched
1153	    }
1154	    matched = 0
1155	    for index in 0..<boundary {
1156	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
1157	        matched = prefixes[matched - 1]
1158	      }
1159	      if matched < limit && value[matched] == chars[index] {
1160	        matched += 1
1161	      }
1162	    }
1163	    boundary -= matched
1164	  }
1165	  if boundary == chars.length() {
1166	    text
1167	  } else {
1168	    character_text(chars, 0, boundary) + "[redacted]"
1169	  }
1170	}
