1215	  match value {
1216	    Json::String(text) if text != "" && secret => {
1217	      let destination = result.secrets
1218	      diagnostic_add_protected(text, output, uncertain, destination, result)
1219	      for line in text.split("\n") {
1220	        if line != "" && line.length() < text.length() {
1221	          diagnostic_add_protected(
1222	            line.to_owned(),
1223	            output,
1224	            uncertain,
1225	            destination,
1226	            result,
1227	          )
1228	        }
1229	        for word in line.split(" ") {
1230	          for part in word.split("=") {
1231	            if part != "" && part.length() < text.length() {
1232	              diagnostic_add_protected(
1233	                part.to_owned(),
1234	                output,
1235	                uncertain,
1236	                destination,
1237	                result,
1238	              )
1239	            }
1240	          }
1241	        }
1242	      }
1243	      let escaped = Json::string(text).stringify()
1244	      if escaped.length() > 2 {
1245	        let encoded = escaped[1:escaped.length() - 1].to_owned()
1246	        if encoded != text {
1247	          diagnostic_add_protected(
1248	            encoded, output, uncertain, destination, result,
1249	          )
1250	        }
1251	      }
1252	    }
1253	    Json::String(text) if text != "" => {
1254	      let mut next_secret = false
1255	      for word in text.split(" ") {
1256	        let word = word.to_owned()
1257	        if next_secret {
1258	          diagnostic_add_protected(
1259	            word,
1260	            output,
1261	            uncertain,
1262	            result.secrets,
1263	            result,
1264	          )
