1280	      }
1281	    }
1282	    Json::Array(values) =>
1283	      for item in values {
1284	        diagnostic_protected_values(
1285	          item,
1286	          result,
1287	          output,
1288	          uncertain,
1289	          secret~,
1290	          depth=depth + 1,
1291	        )
1292	      }
1293	    Json::Object(values) =>
1294	      for name, item in values {
1295	        let key = name.to_lower().replace_all(old="_", new="")
