  1248	            encoded, output, uncertain, destination, result,
  1249	          )
  1250	        }
  1251	      }
  1252	    }
  1253	    Json::String(text) if text != "" => {
  1254	      let mut next_secret = REDACTED  1255	      for word in text.split(" ") {
  1256	        let word = word.to_owned()
  1257	        if next_secret {
  1258	          diagnostic_add_protected(
