 303	fn diagnostic_json(
 304	  value : Json,
 305	  environment : Map[String, String],
 306	  protected_secrets : Array[String],
 307	  truncated : Ref[Bool],
 308	  depth : Int32,
 309	  stable_activity~ : Bool = false,
 310	  secret_states~ : Bool = false,
 311	  stable_operation~ : Bool = false,
 312	  stable_arguments~ : Bool = false,
 313	) -> Json {
 314	  if depth >= 64 {
 315	    truncated.val = true
 316	    return Json::string("[nested evidence omitted]")
 317	  }
 318	  match value {
 319	    Json::Object(values) => {
 320	      let result = Json::empty_object()
 321	      for name, item in values {
 322	        let key = name.to_lower().replace_all(old="_", new="")
 323	        let safe_name = if (
 324	            stable_arguments &&
