 753	async fn try_flush_diagnostic_recording() -> Unit {
 754	  if diagnostic_write_active.val ||
 755	    (diagnostic_pending.is_empty() && diagnostic_recording_health.dropped == 0) {
 756	    return
 757	  }
 758	  diagnostic_write_active.val = true
 759	  defer {
 760	    diagnostic_write_active.val = false
 761	  }
 762	  let mut failure_phase = "directory"
 763	  let mut waiting_for_lock = false
 764	  let mut health_changed = false
 765	  @async.with_timeout(50, async fn() {
 766	    let dir = adapter_state_home()
 767	    @fs.mkdir(dir, permission=0o700, recursive=true, allow_exist=true)
 768	    @fs.chmod(dir, 0o700)
 769	    let path = dir + "/events.jsonl"
 770	    let lock_path = dir + "/events.lock"
 771	    failure_phase = "lock"
 772	    if @fs.exists(lock_path) &&
 773	      @fs.kind(lock_path, follow_symlink=false) != @fs.FileKind::Regular {
 774	      diagnostic_recording_warning("invalid_lock", phase=failure_phase)
 775	      return
 776	    }
 777	    let lock = @fs.open(
 778	      lock_path,
 779	      mode=ReadWrite,
