 781	      permission=0o600,
 782	    )
 783	    defer lock.close()
 784	    if !lock.try_lock(Exclusive) {
 785	      waiting_for_lock = true
 786	      let started_waiting = @env.now()
 787	      let mut acquired = false
 788	      while !diagnostic_recording_health.incident &&
 789	            @env.now() - started_waiting < 20UL {
