 816	        field(pending.event, "status") == Some(Json::string("finished"))
 817	      })
 818	    if @fs.exists(path) {
 819	      let file = @fs.open(path, mode=ReadOnly)
 820	      defer file.close()
 821	      let size = file.size()
 822	      if size > 262144L {
 823	        let marker = diagnostic_recording_event("rotated", "retention_limit")
 824	        set_field(
 825	          marker,
 826	          "missingThroughTime",
 827	          Json::string(@env.now().to_string()),
 828	        )
 829	        set_field(marker, "missingRange", Json::string("unknown"))
 830	        let records = diagnostic_retained_records(file, size)
 831	        retained = Some(records)
 832	        prefix = marker.stringify() + "\n" + records
 833	        prefix_markers += 1
 834	        replace = true
 835	      } else if size > 0L {
