1359	            "--result-format",
1360	            "json",
1361	            "workspace",
1362	            "up",
1363	            required(state, "workspaceId"),
1364	            "--ide-launch",
1365	            "skip",
1366	          ] +
1367	          orca_storage_args(state),
1368	          "workspace-resume",
1369	        ),
1370	      )
1371	      let expires = connection_deadline()
1372	      idle_reset(state, "workspace_resumed")
1373	      connection_timeout(expires, async fn() {
1374	        let port = if required(state, "connection") == "orca-server" {
1375	          Some(reserve_server_port(state))
1376	        } else {
1377	          None
1378	        }
1379	        ensure_ssh_worker(state, port, deadline=expires)
1380	        codex_addon(state)
1381	        if required(state, "connection") == "orca-server" {
1382	          ignore(recover_server(state))
1383	        }
1384	        emit_connection(state, false, existing=previous, deadline=expires)
1385	      })
1386	    }
1387	    "recover" | "restart" => {
1388	      recover_connection(state, restart=mode == "restart", deadline?)
1389	      let connection = field(previous, "connection").unwrap()
1390	      write_connection(state, connection)
1391	    }
1392	    "suspend" => {
1393	      pause_tunnel(state)
1394	      defer unpause_tunnel(state)
1395	      stop_workspace(state)
1396	    }
1397	    "destroy" => {
1398	      pause_tunnel(state)
1399	      errdefer unpause_tunnel(state)
1400	      ignore(
1401	        devsy(
1402	          state,
1403	          [
1404	            "workspace",
1405	            "delete",
1406	            required(state, "workspaceId"),
1407	            "--ignore-not-found",
1408	          ],
1409	          "workspace-delete",
1410	        ),
1411	      )
1412	      cleanup_orca_volume(state)
1413	      if field(state, "tunnelDirectory") is Some(Json::String(directory)) {
1414	        for name in ["server-update-pending", "server-update-complete"] {
1415	          if @fs.exists(directory + "/" + name) {
1416	            @fs.remove(directory + "/" + name)
1417	          }
1418	        }
1419	      }
1420	      close_tunnel(state)
1421	    }
1422	    _ => raise AdapterError("Unknown command")
1423	  }
1424	  save_diagnostic(mode, "success")
1425	  progress_message(mode + ": done (" + progress_timing(progress_started) + ")")
1426	}
