1438	///|
1439	pub async fn execute(mode : String) -> Unit {
1440	  defer @async.protect_from_cancel(async fn() { finish_diagnostic_recording() })
1441	  let mut failure_recorded = false
1442	  errdefer (if !failure_recorded && @async.is_being_cancelled() {
1443	    @async.protect_from_cancel(async fn() {
1444	      save_diagnostic(mode, "cancelled", error_type="cancelled")
1445	    })
1446	  })
1447	  execute_inner(mode) catch {
1448	    InvalidConfig(message) => {
1449	      let detail = diagnostic_error(InvalidConfig(message))
1450	      progress_message(detail + " (" + progress_timing(progress_started) + ")")
1451	      save_command_failure(mode, InvalidConfig(message))
1452	      failure_recorded = true
1453	      raise InvalidConfig(message)
1454	    }
1455	    AdapterError(message) => {
1456	      let detail = diagnostic_error(AdapterError(message))
1457	      progress_message(detail + " (" + progress_timing(progress_started) + ")")
1458	      save_command_failure(mode, AdapterError(message))
1459	      failure_recorded = true
1460	      raise AdapterError(message)
1461	    }
1462	    error => {
1463	      progress_message(
1464	        mode + ": failed (" + progress_timing(progress_started) + ")",
1465	      )
1466	      save_command_failure(mode, error)
1467	      failure_recorded = true
1468	      raise AdapterError(
1469	        mode +
1470	        " failed: unexpected runtime error; diagnostic run " +
1471	        recording_run_id,
1472	      )
1473	    }
1474	  }
1475	}
