123	fn sensitive_name(name : String) -> Bool {
124	  let normalized = name.to_lower().replace_all(old="-", new="_")
125	  if ["_enabled", "_disabled", "_count", "_mode", "_method"]
126	    .iter()
127	    .any(suffix => normalized.has_suffix(suffix)) {
128	    return false
129	  }
130	  let credential = credential_field(name, for_diagnostics=true)
131	  let name = name.to_lower()
132	  credential ||
133	  [
134	    "password", "passwd", "passphrase", "token", "secret", "api_key", "apikey", "auth",
135	    "credential", "private_key", "access_key", "storage_key", "cookie", "fnox_age_key",
136	  ]
137	  .iter()
138	  .any(marker => name.contains(marker))
139	}
