299	async fn Progress::status(self : Progress, event : Json) -> Unit {
300	  guard field(event, "phase") is Some(Json::String(phase)) &&
301	    phase_label(phase) is Some(label) &&
302	    field(event, "state") is Some(Json::String(state)) &&
303	    ["started", "succeeded", "failed", "skipped"].contains(state) else {
304	    return
305	  }
306	  if self.phase_count < 128 {
307	    self.phase_count += 1
308	    save_diagnostic(
309	      self.stage,
310	      state,
311	      phase~,
312	      error_type?=if state == "failed" { Some("backend_phase") } else { None },
313	      evidence?=self.context,
314	      evidence_stable_operation=true,
315	      protected_secrets=self.secrets,
316	      recording=self.recording,
317	    )
318	  } else if self.phase_count == 128 {
319	    self.phase_count += 1
320	    self.details_truncated = true
321	    save_diagnostic(
322	      self.stage,
323	      "diagnostics-truncated",
324	      error_type="phase_limit",
325	      phase~,
326	      evidence?=self.context,
327	      evidence_incomplete=true,
328	      evidence_stable_operation=true,
329	      protected_secrets=self.secrets,
330	      recording=self.recording,
331	    )
332	  }
333	  let key = ["pipeline", "operationId", "phase", "step"]
334	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
335	    .join(":")
336	  if state == "started" {
337	    if self.operations.length() >= 256 {
338	      self.operations.clear()
339	    }
340	    self.operations.set(key, @env.now())
341	    progress_message(label + ": running…")
342	  } else {
343	    let duration = match field(event, "durationMs") {
344	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
345	        Some(seconds(value.to_uint64()))
346	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
347	    }
348	    self.operations.remove(key)
349	    let timing = duration.map(value => value + ", ").unwrap_or("") +
350	      "elapsed " +
351	      seconds(@env.now() - progress_started)
352	    progress_message(
353	      label +
354	      ": " +
355	      (if state == "succeeded" { "done" } else { state }) +
356	      " (" +
357	      timing +
358	      ")",
359	    )
360	  }
361	}
