363	///|
378	async fn Progress::message(
379	  self : Progress,
380	  text : String,
381	  debug~ : Bool,
382	  warning~ : Bool,
383	  emit~ : Bool = true,
384	) -> Unit {
385	  if self.protection_incomplete {
386	    self.details_truncated = true
387	    self.remember(
388	      "error detail unavailable because workspace protection values could not be read",
389	      warning=true,
390	    )
391	    return
392	  }
393	  for line in text.split("\n") {
394	    let text = line.trim().to_owned()
395	    if text == "" {
396	      continue
397	    }
398	    guard self.safe_message(text) is Some(safe) else {
399	      self.details_truncated = true
400	      continue
401	    }
402	    if !debug || warning {
403	      self.remember(safe, warning~)
404	    }
405	    if !emit {
406	      continue
407	    }
408	    if safe.has_prefix("#") {
409	      guard safe.split_once(" ") is Some((id, rest)) &&
410	        id.length() > 1 &&
411	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
412	        continue
413	      }
414	      let detail = rest.trim().to_owned()
415	      guard detail.has_prefix("[") ||
416	        detail.has_prefix("DONE") ||
417	        detail.has_prefix("ERROR") ||
418	        detail.has_prefix("CACHED") else {
419	        continue
420	      }
421	      if detail.has_prefix("ERROR") && debug && !warning {
422	        self.remember(safe, warning=true)
423	      }
424	      if self.builds.get(id.to_owned()) == Some(detail) {
425	        continue
426	      }
427	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
428	        self.builds.set(id.to_owned(), detail)
429	      }
430	      progress_message("Build " + id.to_owned() + ": " + detail)
431	    } else if classic_build_step(safe) {
432	      // Classic RUN output has no prefix. Only its own completion marker
433	      // ends this mode; phase events on another pipe can arrive ahead of it.
434	      self.classic_build = true
435	      progress_message("Build " + safe)
436	    } else if safe.has_prefix("Successfully built ") ||
437	      safe.has_prefix("Successfully tagged ") {
438	      self.classic_build = false
439	      progress_message("Build: " + safe)
440	    } else if self.classic_build && !warning {
441	      continue
442	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
443	      progress_message(self.stage + ": " + safe)
444	    } else if !debug && safe.has_prefix("[credential") {
445	      progress_message(self.stage + ": " + safe)
446	    }
447	  }
448	}
