 344	fn up_arguments_evidence(
 345	  args : Array[String],
 346	  sources : Array[String],
 347	) -> (Json, Array[String], Bool) {
 348	  let secrets : Array[String] = []
 349	  for index, argument in args {
 350	    if argument.has_prefix("-") &&
 351	      credential_argument(argument) &&
 352	      !argument.contains("=") &&
 353	      index + 1 < args.length() {
 354	      add_protected_secret(secrets, args[index + 1])
 355	    }
 356	    if argument.split_once("=") is Some((name, value)) {
 357	      if credential_argument(name.to_owned()) {
 358	        add_protected_secret(secrets, value.to_owned())
 359	      } else if name == "--provider-option" &&
 360	        value.split_once("=") is Some((key, setting)) &&
 361	        credential_argument(key.to_owned()) {
 362	        add_protected_secret(secrets, setting.to_owned())
 363	      }
 364	    }
 365	    if secrets.length() > 512 {
 366	      return (
 367	        { "argumentCount": args.length(), "reason": "protected_value_limit" },
 368	        [],
 369	        true,
 370	      )
 371	    }
 372	  }
 373	  let arguments : Array[Json] = args.mapi((index, value) => {
 374	    "value": value,
 375	    "source": sources[index],
 376	  })
 377	  ({ "arguments": arguments }, secrets, false)
