1639	///|
1640	fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
1641	  match value {
1642	    None => { "state": "unset" }
1643	    Some("") => { "state": "empty" }
1644	    Some(text) => {
1645	      let valid = match kind {
1646	        Commit => valid_commit(text)
1647	        Workspace => valid_workspace_id(text)
1648	        Identity => text.length() <= 128 && valid_context(text)
1649	        RefName => diagnostic_ref(text)
1650	      }
1651	      let credential_form = text
1652	        .split("/")
1653	        .iter()
1654	        .any(part => {
1655	          [
1656	            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
1657	            "eyJ",
1658	          ]
1659	          .iter()
1660	          .any(prefix => part.has_prefix(prefix))
1661	        })
1662	      if credential_form {
1663	        { "state": "redacted" }
1664	      } else if valid {
1665	        { "state": "valid", "value": text }
1666	      } else {
1667	        { "state": "invalid", "value": text }
1668	      }
1669	    }
1670	  }
1671	}
