1673	///|
1674	// A recording grammar, never a replacement for checkout validation. Excludes
1675	// URLs, credential forms, control characters and Git's invalid ref syntax.
1676	fn diagnostic_ref(text : String) -> Bool {
1677	  text.length() <= 1024 &&
1678	  !text.has_prefix("-") &&
1679	  !text.contains("..") &&
1680	  !text.contains("@{") &&
1681	  text != "@" &&
1682	  text
1683	  .split("/")
1684	  .iter()
1685	  .all(part => {
1686	    part != "" &&
1687	    !part.has_prefix(".") &&
1688	    !part.has_suffix(".") &&
1689	    !part.has_suffix(".lock")
1690	  }) &&
1691	  text
1692	  .iter()
1693	  .all(c => {
1694	    c > ' ' &&
1695	    c != '\u007f' &&
1696	    !['~', '^', ':', '?', '*', '[', '\\'].contains(c)
1697	  })
1698	}
