1801	///|
1802	// Inspect only the strategy flags in the actual invocation. Other arguments
1803	// never enter the diagnostic record. Devsy uses the last valid repeated flag.
1804	fn diagnostic_clone_strategy(args : Array[String]) -> (String, String) {
1805	  let mut strategy = "full"
1806	  let mut count = 0
1807	  let mut invalid = false
1808	  let mut index = 0
1809	  while index < args.length() {
1810	    let argument = args[index]
1811	    let value = if argument == "--git-clone-strategy" {
1812	      count += 1
1813	      index += 1
1814	      if index < args.length() {
1815	        Some(args[index])
1816	      } else {
1817	        None
1818	      }
1819	    } else if argument.has_prefix("--git-clone-strategy=") {
1820	      count += 1
1821	      Some(argument[21:].to_owned())
1822	    } else {
1823	      None
1824	    }
1825	    if count > 0 &&
1826	      (
1827	        argument == "--git-clone-strategy" ||
1828	        argument.has_prefix("--git-clone-strategy=")
1829	      ) {
1830	      match value {
1831	        Some("") => strategy = "full"
1832	        Some("shallow" | "blobless" | "treeless" | "bare" as known) =>
1833	          strategy = known
1834	        _ => invalid = true
1835	      }

