 34	///|
 35	fn string_field(
 36	  value : Json,
 37	  name : String,
 38	  location : String,
 39	) -> String? raise ConfigError {
 40	  match field(value, name) {
 41	    None => None
 42	    Some(Json::String(text)) => Some(text)
 43	    _ => raise InvalidConfig("\{location}.\{name} must be a string")
 44	  }
 45	}
 46	
 47	///|
 48	fn object_field(
 49	  value : Json,
 50	  name : String,
 51	  location : String,
 52	) -> Json raise ConfigError {
 53	  match field(value, name) {
 54	    None => Json::empty_object()
 55	    Some(Json::Object(_) as object) => object
 56	    _ => raise InvalidConfig("\{location}.\{name} must be a mapping")
 57	  }
 58	}
 59	
 60	///|
 61	fn args_field(
 62	  value : Json,
 63	  location : String,
 64	) -> Array[String] raise ConfigError {
 65	  match field(value, "upArgs") {
 66	    None => []
 67	    Some(Json::Array(items)) =>
 68	      items.map(item => {
 69	        match item {
 70	          Json::String(text) => text
 71	          _ => raise InvalidConfig("\{location}.upArgs must contain strings")
 72	        }
 73	      })
 74	    _ => raise InvalidConfig("\{location}.upArgs must be an array")
 75	  }
 76	}
 77	
 78	///|
 79	fn command_field(
 80	  value : Json,
 81	  location : String,
 82	) -> Array[String]? raise ConfigError {
 83	  match field(value, "command") {
 84	    None => None
 85	    Some(Json::Array(items)) => {
 86	      guard items.length() > 0 else {
 87	        raise InvalidConfig("\{location}.command must be a nonempty array")
 88	      }
 89	      let command = items.mapi((index, item) => {
 90	        match item {
 91	          Json::String(text) => {
 92	            guard !text.contains("\u0000") && (index != 0 || text != "") else {
 93	              raise InvalidConfig(
 94	                "\{location}.command[\{index}] must not contain NUL or have an empty executable",
 95	              )
 96	            }
 97	            text
 98	          }
 99	          _ =>
100	            raise InvalidConfig(
101	              "\{location}.command[\{index}] must be a string",
102	            )
103	        }
104	      })
105	      Some(command)
106	    }
107	    _ => raise InvalidConfig("\{location}.command must be an array of strings")
108	  }
109	}
