168	///|
169	fn resolve_settings_with_sources(
170	  document : Json,
171	  recipe_id : String,
172	  lookup : (String) -> String?,
173	) -> (Settings, Array[String]) raise ConfigError {
174	  let common = object_field(document, "devsy", "orca.yaml")
