   112	fn valid_env_name(name : String) -> Bool {
   113	  let characters = name.to_array()
   114	  characters.length() > 0 &&
   115	  !(characters[0] >= '0' && characters[0] <= '9') &&
   116	  characters
   117	  .iter()
   118	  .all(char => {
   119	    char == '_' ||
   120	    (char >= 'a' && char <= 'z') ||
   121	    (char >= 'A' && char <= 'Z') ||
   122	    (char >= '0' && char <= '9')
   123	  })
   124	}
