   169	fn resolve_settings_with_sources(
   170	  document : Json,
   171	  recipe_id : String,
   172	  lookup : (String) -> String?,
   173	) -> (Settings, Array[String]) raise ConfigError {
   174	  let common = object_field(document, "devsy", "orca.yaml")
   175	  let recipes = match field(document, "environmentRecipes") {
   176	    Some(Json::Array(items)) => items
   177	    _ => raise InvalidConfig("orca.yaml.environmentRecipes must be an array")
   178	  }
   179	  let selected = recipes.filter(recipe => {
   180	    field(recipe, "id") == Some(Json::string(recipe_id))
   181	  })
   182	  guard selected.length() == 1 else {
   183	    raise InvalidConfig(
   184	      "Expected exactly one environment recipe named \{recipe_id}",
   185	    )
   186	  }
   187	  let specific = object_field(
   188	    selected[0],
   189	    "devsy",
   190	    "environmentRecipes.\{recipe_id}",
   191	  )
   192	  let profile_name = match string_field(specific, "profile", "recipe.devsy") {
   193	    Some(name) => Some(name)
   194	    None => string_field(common, "profile", "devsy")
