   196	  let profiles = object_field(common, "profiles", "devsy")
   197	  let mut profile_location = "devsy.profiles"
   198	  let profile = match profile_name {
   199	    Some(raw_name) => {
   200	      let name = interpolate(raw_name, lookup, "devsy.profile")
   201	      profile_location = "devsy.profiles." + name
   202	      match field(profiles, name) {
   203	        Some(Json::Object(_) as value) => value
   204	        _ => raise InvalidConfig("Unknown devsy profile")
   205	      }
   206	    }
   207	    None => Json::empty_object()
   208	  }
   209	  let layers = [common, profile, specific]
   210	  let mut command = ["devsy"]
   211	  let mut home = None
   212	  let mut context = None
   213	  let mut build_ref = None
   214	  let mut connection = None
   215	  let mut codex_auth = false
   216	  let mut idle_timeout_ms = None
   217	  let mut idle_timeout_source = None
   218	  let args = []
   219	  let arg_sources = []
   220	  let server_env = Json::empty_object()
   221	  for index, layer in layers {
   222	    let location = [
   223	        "devsy",
   224	        profile_location,
   225	        "environmentRecipes." + recipe_id + ".devsy",
   226	      ][index]
   227	    if command_field(layer, location) is Some(raw) {
   228	      let expanded = raw.mapi((argument_index, argument) => {
   229	        interpolate(argument, lookup, "\{location}.command[\{argument_index}]")
   230	      })
   231	      let value = Json::empty_object()
   232	      set_field(value, "command", Json::array(expanded.map(Json::string)))
   233	      command = command_field(value, location).unwrap()
   234	    }
   235	    for
   236	      pair in [
   237	        ("home", string_field(layer, "home", location)),
   238	        ("context", string_field(layer, "context", location)),
   239	        ("buildRef", string_field(layer, "buildRef", location)),
   240	        ("connection", string_field(layer, "connection", location)),
   241	      ] {
   242	      let (name, value) = pair
   243	      if value is Some(raw) {
   244	        let expanded = interpolate(raw, lookup, "\{location}.\{name}")
   245	        match name {
   246	          "home" => home = Some(expanded)
   247	          "context" => context = Some(expanded)
   248	          "buildRef" => build_ref = Some(expanded)
   249	          _ => connection = Some(expanded)
   250	        }
   251	      }
   252	    }
   253	    for argument_index, argument in args_field(layer, location) {
   254	      args.push(
   255	        interpolate(argument, lookup, "\{location}.upArgs[\{argument_index}]"),
   256	      )
   257	      arg_sources.push("\{location}.upArgs[\{argument_index}]")
   258	    }
   259	    let server = object_field(layer, "orca-server", location)
   260	    let configured_env = object_field(server, "env", location + ".orca-server")
   261	    if configured_env is Json::Object(values) {
   262	      for name, value in values {
   263	        let setting_location = location + ".orca-server.env." + name
   264	        guard valid_env_name(name) else {
   265	          raise InvalidConfig(setting_location + " has an invalid name")
   266	        }
   267	        ignore(interpolate("${" + name + "}", _ => None, setting_location))
   268	        guard value is Json::String(text) && !text.contains("\u0000") else {
   269	          raise InvalidConfig(
   270	            setting_location + " must be a string without NUL",
   271	          )
   272	        }
   273	        let literal = interpolate(text, _ => Some(""), setting_location)
   274	        guard !(credential_field(name) && literal != "") &&
   275	          redact_credentials(text, for_diagnostics=false) == text else {
   276	          raise InvalidConfig(
   277	            setting_location + ": credential values must use remote references",
   278	          )
   279	        }
   280	        set_field(server_env, name, value)
   281	      }
   282	    }
   283	    let addons = object_field(layer, "addons", location)
   284	    if string_field(layer, "idleTimeout", location) is Some(raw) {
   285	      idle_timeout_ms = Some(
   286	        parse_idle_timeout(interpolate(raw, lookup, "\{location}.idleTimeout")) catch {
   287	          InvalidConfig(message) =>
   288	            raise InvalidConfig("\{location}.idleTimeout: " + message)
   289	        },
   290	      )
   291	      idle_timeout_source = Some(location + ".idleTimeout")
   292	    }
   293	    match field(addons, "codexAuth") {
   294	      None => ()
   295	      Some(Json::True) => codex_auth = true
   296	      Some(Json::False) => codex_auth = false
   297	      _ => raise InvalidConfig("\{location}.addons.codexAuth must be a boolean")
   298	    }
   299	  }
   300	  let connection = match connection {
   301	    Some("orca-server") => Server
   302	    Some("ssh") => Ssh
   303	    _ =>
   304	      raise InvalidConfig(
   305	        "devsy.connection must explicitly select orca-server or ssh",
   306	      )
   307	  }
   308	  (
   309	    {
   310	      connection,
   311	      command,
   312	      home,
   313	      context,
   314	      build_ref,
   315	      up_args: args,
   316	      codex_auth,
   317	      server_env,
   318	      idle_timeout_ms,
   319	      idle_timeout_source,
   320	    },
   321	    arg_sources,
   322	  )
   323	}
