208	///|
209	async fn bulk_context(state : Json) -> String {
210	  let selection = @json.parse(state.stringify())
211	  if selection is Json::Object(fields) {
212	    fields.remove("context")
213	  }
214	  let contexts = @json.parse(
215	    devsy(
216	      selection,
217	      ["--result-format", "json", "context", "list"],
218	      "bulk-context",
219	    ),
220	  )
221	  guard contexts is Json::Array(items) else {
222	    raise AdapterError("Invalid context list")
223	  }
224	  let selected = items.filter(item => {
225	    field(item, "default") == Some(Json::boolean(true))
226	  })
227	  guard selected.length() == 1 else {
228	    raise AdapterError("No unique effective Devsy context")
229	  }
230	  required(selected[0], "name")
