551	///|
552	async fn bulk_inner(
553	  mode : String,
554	  args : Array[String],
555	  recording_allowed : Ref[Bool],
556	) -> Int32 {
557	  let options = bulk_options(mode, args)
558	  save_diagnostic("bulk", "started", evidence={
559	    "action": mode,
560	    "provider": options.provider,
561	    "jobs": options.jobs,
562	    "force": options.force,
563	  })
564	  let base = adapter_state_home() + "/tunnels"
565	  let states : Array[Json] = []
566	  let discovery_errors : Array[Json] = []
567	  let discovery_secrets : Array[String] = []
568	  let mut discovery_recording = true
569	  if @fs.exists(base) {
570	    for name in @fs.readdir(base, sort=true) {
571	      let directory = base + "/" + name
572	      let mut discovery_phase = "kind"
573	      try {
574	        if @fs.kind(directory, follow_symlink=false) != @fs.FileKind::Directory ||
575	          !@fs.exists(directory + "/enabled") {
576	          continue
577	        }
578	        discovery_phase = "read"
579	        let raw = @fs.read_file(directory + "/state.json").text()
580	        discovery_phase = "parse"
581	        let state = @json.parse(raw)
582	        discovery_phase = "validate"
583	        validate_state(state)
584	        guard field(state, "devsyEnv") is Some(Json::Object(_)) else {
585	          raise AdapterError("Missing saved Devsy environment")
586	        }
587	        ignore(required(state, "workspaceUid"))
588	        ignore(required(state, "context"))
589	        set_field(state, "tunnelDirectory", Json::string(directory))
590	        set_field(state, "provider", Json::string(options.provider))
591	        snapshot_workspace_recording(state, directory)
592	        states.push(state)
593	      } catch {
594	        error => {
595	          discovery_errors.push({
596	            "savedState": directory,
597	            "reason": diagnostic_error(error),
598	          })
599	          let (allowed, secrets) = record_discovery_error(
600	            "bulk-discovery", directory, discovery_phase, error,
601	          )
602	          discovery_recording = discovery_recording && allowed
603	          for secret in secrets {
604	            discovery_secrets.push(secret)
605	          }
606	        }
607	      }
608	    }
609	  }
610	  recording_allowed.val = recording_allowed.val &&
611	    discovery_recording &&
612	    states.iter().all(workspace_recording)
613	  if !recording_allowed.val {
614	    diagnostic_recording_health.run_partial = true
615	  }
616	  let keys : Map[String, Int32] = Map([])
617	  for state in states {
618	    let key = required(state, "context") + ":" + required(state, "workspaceUid")
619	    keys.set(key, keys.get(key).unwrap_or(0) + 1)
620	  }
621	  let results : Array[Json] = []
622	  let permits = @async.Semaphore(options.jobs)
623	  @async.with_task_group(async fn(group) {
624	    for state in states {
625	      let key = required(state, "context") +
626	        ":" +
627	        required(state, "workspaceUid")
628	      if keys.get(key) != Some(1) {
629	        discovery_errors.push({
630	          "savedState": required(state, "tunnelDirectory"),
631	          "reason": "duplicate_saved_identity",
632	        })
633	        record_selection_failure(
634	          "bulk-discovery", state, "identity", "duplicate_saved_identity", "Duplicate saved workspace identity",
635	        )
636	        continue
637	      }
638	      permits.acquire()
639	      group.spawn_bg(async fn() {
640	        defer permits.release()
641	        if bulk_one(mode, state, options) is Some(result) {
642	          results.push(result)
643	        }
644	      })
645	    }
646	  })
647	  results.sort_by((a, b) => {
648	    let a_id = match field(a, "id") {
649	      Some(Json::String(id)) => id
650	      _ => ""
651	    }
652	    let b_id = match field(b, "id") {
653	      Some(Json::String(id)) => id
654	      _ => ""
655	    }
656	    a_id.compare(b_id)
657	  })
658	  let failures = results
659	    .filter(r => field(r, "outcome") == Some(Json::string("failed")))
660	    .length()
661	  let output : Json = {
662	    "schemaVersion": 1,
663	    "action": mode,
664	    "provider": options.provider,
665	    "workspaces": results,
666	    "failed": failures,
667	    "discoveryErrors": discovery_errors,
668	  }
669	  @stdio.stdout.write(output.stringify(indent=2) + "\n")
670	  recording_allowed.val = recording_allowed.val &&
671	    states.iter().all(workspace_recording)
672	  let secrets : Array[String] = [] + discovery_secrets
673	  for state in states {
674	    match saved_workspace_secrets(state) {
675	      Some(values) =>
676	        for secret in values {
677	          secrets.push(secret)
678	        }
679	      None => {
680	        suppress_workspace_recording(state)
681	        recording_allowed.val = false
682	      }
683	    }
684	  }
685	  if !recording_allowed.val {
686	    diagnostic_recording_health.run_partial = true
687	  }
688	  save_diagnostic(
689	    "bulk",
690	    if failures > 0 {
691	      "failed"
692	    } else if !discovery_errors.is_empty() {
693	      "partial"
694	    } else {
695	      "success"
696	    },
697	    error_type?=if !discovery_errors.is_empty() {
698	      Some("saved_state_invalid")
699	    } else {
700	      None
701	    },
702	    evidence=output,
703	    evidence_incomplete=results
704	      .iter()
705	      .any(result => {
706	        field(result, "evidenceTruncated") == Some(Json::boolean(true))
707	      }),
708	    evidence_stable_activity=true,
709	    protected_secrets=secrets,
710	    recording=recording_allowed.val,

196	async fn launch_server(state : Json, update_marker? : (String, String)) -> Json {
197	  let root = required(state, "projectRoot")
198	  let port = reserve_server_port(state)
199	  let configured_env = field(state, "serverEnv").unwrap_or(Json::empty_object())
200	  let diagnostic_env = Json::empty_object()
201	  if configured_env is Json::Object(values) {
202	    for name, value in values {
203	      if value is Json::String(text) {
204	        set_field(diagnostic_env, name, Json::string(redact_credentials(text)))
205	      }
206	    }
207	  }
208	  let protected_values = workspace_output_secrets(state)
209	  if protected_values is None {
210	    suppress_workspace_recording(state)
211	  }
212	  let recording = state_recording(state)
213	  let launch = (if field(state, "orcaVolume") is Some(_) {
214	      "export ORCA_USER_DATA_PATH=/worktrees/.orca; "
215	    } else {
216	      ""
217	    }) +
218	    server_launch_script(root, port, configured_env, recording~, update_marker?)
219	  let script = if update_marker is Some(_) {
220	    server_update_locked(launch, inline_launch=true)
221	  } else {
222	    launch
223	  }
224	  let (status, raw_output, detail) = command_result(
225	    workspace_program(state, "ssh"),
226	    mux_ssh_args(state) + [script],
227	    "orca-serve",
228	    environment=workspace_environment(state),
229	    recording_override=state_recording(state),
230	    protected_secrets?=protected_values,
231	    protection_incomplete=protected_values is None,
232	    cwd?=workspace_directory(state).map(path => path[:]),
233	  )
234	  let mut output = raw_output
235	  if recording {
236	    let mut observed = None
237	    let mut truncated = Json::array([])
238	    let mut observation_error = false
239	    if raw_output.split_once("\n") is Some((first, remaining)) {
240	      let event = @json.parse(first.to_owned()) catch { _ => Json::null() }
241	      if field(event, "kind") == Some(Json::string("result")) &&
242	        field(event, "serverEnvironment") is Some(value) {
243	        observed = Some(value)
244	        truncated = field(event, "truncated").unwrap_or(Json::array([]))
245	        observation_error = field(event, "observationError") ==
246	          Some(Json::boolean(true))
247	        output = remaining.to_owned()
248	      }
249	    }
250	    let complete = (
251	        configured_env == Json::empty_object() || observed is Some(_)
252	      ) &&
253	      truncated == Json::array([]) &&
254	      !observation_error
255	    let pairing = workspace_pairing_secrets(state)
256	    if pairing is None {
257	      suppress_workspace_recording(state)
258	    }
259	    save_diagnostic(
260	      "server-environment",
261	      if complete {
262	        "observed"
263	      } else {
264	        "partial"
265	      },
266	      evidence={
267	        "templates": diagnostic_env,
268	        "references": observed.unwrap_or(Json::null()),
269	        "completeness": if complete {
270	          "complete"
271	        } else {
272	          "partial"
273	        },
274	        "missingReason": if complete {
275	          Json::null()
276	        } else if observed is None || observation_error {
277	          "observation_failed"
278	        } else {
279	          "value_truncated"
280	        },
281	        "truncatedReferences": truncated,
282	      },
283	      evidence_incomplete=!complete,
284	      protected_secrets?=pairing,
285	      environment=workspace_environment(state),
286	      recording=recording && pairing is Some(_),
287	    )
288	  }
289	  guard status == 0 else {
290	    raise AdapterError(command_failure("orca-serve", status, detail))
291	  }
292	  let result = @json.parse(output)
293	  let connection = match field(result, "connection") {
294	    Some(value) => value
295	    None => result
296	  }
297	  guard required(connection, "pairingCode") != "" else {
298	    raise AdapterError("Orca returned no pairing code")
299	  }
300	  @fs.write_file(
301	    required(state, "tunnelDirectory") + "/pairing-code",
302	    required(connection, "pairingCode"),
303	    permission=0o600,
304	  )
305	  let output : Json = {
306	    "type": "orca-server",
307	    "pairingCode": required(connection, "pairingCode"),
308	    "projectRoot": root,
309	  }
310	  output
311	}
