322	///|
323	fn server_launch_script(
324	  root : String,
325	  port : Int32,
326	  server_env : Json,
327	  recording~ : Bool = false,
328	  update_marker? : (String, String),
329	) -> String raise {
330	  let names : Map[String, Bool] = Map([])
331	  guard server_env is Json::Object(values) else {
332	    raise AdapterError("Invalid saved server environment")
333	  }
334	  for target, value in values {
335	    guard valid_env_name(target) &&
336	      value is Json::String(text) &&
337	      !text.contains("\u0000") else {
338	      raise AdapterError("Invalid saved server environment")
339	    }
340	    ignore(
341	      interpolate(
342	        text,
343	        name => {
344	          names.set(
345	            name,
346	            names.get(name).unwrap_or(false) ||
347	            credential_field(target, for_diagnostics=true),
348	          )
349	          Some("")
350	        },
351	        "server environment",
352	      ),
353	    )
354	  }
355	  let fields : Array[Json] = []
356	  let inputs = StringBuilder()
357	  for name, secret in names {
358	    fields.push({
359	      "name": name,
360	      "secret": secret || credential_field(name, for_diagnostics=true),
361	    })
362	    if name == "DEVSY_REMOTE_WORKSPACE_FOLDER" {
363	      inputs.write_string(" " + quote("x") + " " + quote(root))
364	    } else {
