1392	///|
1393	async fn DiagnosticCapture::read(
1394	  self : DiagnosticCapture,
1395	  reader : @process.ReadFromProcess,
1396	) -> Unit {
1397	  try {
1398	    while reader.read_some(max_len=4096) is Some(chunk) {
1399	      let remaining = self.limit - self.output.length()
1400	      let count = if chunk.length() < remaining {
1401	        chunk.length()
1402	      } else {
1403	        remaining
1404	      }
1405	      if count > 0 {
1406	        self.output.write_bytes(chunk[:count])
1407	      }
1408	      if count < chunk.length() {
1409	        self.truncated = true
1410	      }
1411	    }
1412	  } catch {
1413	    error =>
1414	      if @async.is_being_cancelled() {
1415	        raise error
1416	      } else {
1417	        self.truncated = true
1418	      }
1419	  }
1420	  self.finished = true
1421	}
