1425	  @async.with_timeout(250, async fn() {
1426	    while captures.iter().any(capture => !capture.finished) {
1427	      @async.sleep(5)
1428	    }
1429	  }) catch {
1430	    error => if @async.is_being_cancelled() { raise error }
1431	  }
1432	}
