1435	async fn diagnostic_process_output(
1436	  program : String,
1437	  args : Array[String],
1438	  environment~ : Map[String, String],
1439	  cwd? : StringView,
1440	  stdin? : &@process.ProcessInput,
1441	  stdout_limit~ : Int32,
1442	  stderr_limit~ : Int32,
1443	) -> (Int32, Bytes, Bool, Bytes, Bool) {
1444	  let (out, stdout) = @process.read_from_process()
1445	  defer out.close()
1446	  let (err, stderr) = @process.read_from_process()
1447	  defer err.close()
1448	  @async.with_task_group(async fn(group) {
1449	    let child = @process.spawn(
1450	      group,
1451	      program,
1452	      args,
1453	      extra_env=environment,
1454	      inherit_env=false,
1455	      cwd?,
1456	      stdin?,
1457	      stdout~,
1458	      stderr~,
1459	    )
1460	    let output = DiagnosticCapture::new(stdout_limit)
1461	    let errors = DiagnosticCapture::new(stderr_limit)
1462	    group.spawn_bg(no_wait=true, async fn() { output.read(out) })
1463	    group.spawn_bg(no_wait=true, async fn() { errors.read(err) })
1464	    let status = child.wait()
1465	    if status == 0 {
1466	      while !output.finished {
1467	        @async.sleep(5)
1468	      }
1469	      wait_diagnostic_captures([errors])
1470	    } else {
1471	      wait_diagnostic_captures([output, errors])
1472	    }
1473	    (
1474	      status,
1475	      output.output.to_bytes(),
1476	      output.truncated || !output.finished,
1477	      errors.output.to_bytes(),
1478	      errors.truncated || !errors.finished,
1479	    )
1480	  })
1481	}
