134	  let directory = adapter_state_home()
135	  save_diagnostic("supervisor-launch", "restart", evidence={
136	    "stateDirectory": directory,
137	  })
138	  errdefer save_diagnostic(
139	    "supervisor-launch",
140	    "failed",
141	    error_type="restart_failed",
142	    evidence={ "stateDirectory": directory },
143	  )
