243	///|
244	async fn supervisor_inner(
245	  directory : String,
246	  startup_hold : Ref[@fs.File?],
247	  initial_workspace? : String,
248	) -> Unit {
249	  publish_file(directory + "/supervisor.pid", proxy_pid().to_string())
250	  recover_diagnostic_health(directory)
251	
252	  let mut released = false
253	  defer (if !released {
254	    @fs.remove(directory + "/supervisor.pid") catch {
255	      _ => ()
256	    }
257	  })
258	  save_diagnostic("supervisor", "started", evidence={
259	    "stateDirectory": directory,
260	  })
261	  defer save_diagnostic("supervisor", "stopped")
262	  let listener = @socket.TcpServer(@socket.Addr::parse("127.0.0.1:0"))
263	  defer listener.close()
264	  let identity : Json = {
265	    "protocol": 1,
266	    "pid": proxy_pid().to_string(),
267	    "start": process_start(proxy_pid()).to_string(),
268	  }
269	  let descriptor : Json = {
270	    "pid": required(identity, "pid"),
271	    "start": required(identity, "start"),
272	    "port": listener.addr.port().to_string(),
273	    "diagnosticHealthPath": "diagnostic-health.json",
274	  }
275	  publish_file(directory + "/supervisor.json", descriptor.stringify())
276	  let environments : Map[String, Map[String, String]] = Map([])
277	  if initial_workspace is Some(workspace) {
278	    let canonical = @fs.realpath(workspace)
279	    guard canonical.has_prefix(@fs.realpath(directory) + "/tunnels/") else {
280	      raise AdapterError("Initial workspace is outside the state directory")
281	    }
282	    let saved = @json.parse(
283	      @fs.read_file(workspace + "/environment.json").text(),
284	    )
285	    guard saved is Json::Object(values) else {
286	      raise AdapterError("Invalid saved workspace environment")
287	    }
288	    let environment : Map[String, String] = Map([])
289	    for (name, value) in values {
290	      guard value is Json::String(value) else {
291	        raise AdapterError("Invalid saved workspace environment")
292	      }
293	      environment.set(name, value)
294	    }
295	    environments.set(canonical, environment)
296	    @fs.write_file(workspace + "/request", "", permission=0o600)
297	  }
298	  let registrations : Ref[Int32] = { val: 0, }
299	  let active : Map[String, Bool] = Map([])
300	  let transports : Map[String, Bool] = Map([])
301	  let mut idle_since = @env.now()
302	  @async.with_task_group(async fn(group) {
303	    group.spawn_bg(no_wait=true, async fn() {
304	      while true {
305	        @async.sleep(250)
306	        if !diagnostic_pending.is_empty() ||
307	          diagnostic_recording_health.dropped > 0 {
308	          try_flush_diagnostic_recording()
309	        }
310	      }
311	    })
312	    let registration_slots = @async.Semaphore(16)
313	    group.spawn_bg(no_wait=true, async fn() {
314	      while true {
315	        registration_slots.acquire()
316	        let (socket, _) = listener.accept()
317	        registrations.val += 1
318	        group.spawn_bg(no_wait=true, async fn() {
319	          defer {
320	            registrations.val -= 1
321	            registration_slots.release()
322	          }
323	          accept_registration(socket, directory, environments, identity) catch {
324	            _ => ()
325	          }
326	        })
327	      }
328	    })
329	    while @fs.exists(directory) {
330	      if @fs.exists(directory + "/shutdown") {
331	        return
332	      }
333	      for workspace in environments.keys().to_array() {
334	        if !@fs.exists(workspace) {
335	          environments.remove(workspace)
336	        }
337	      }
338	      let base = directory + "/tunnels"
339	      if @fs.exists(base) {
340	        for name in @fs.readdir(base) {
341	          let workspace = base + "/" + name
342	          try {
343	            let requested = @fs.exists(workspace + "/request")
344	            if !requested {
345	              continue
346	            }
347	            let canonical = @fs.realpath(workspace)
348	            guard environments.get(canonical) is Some(environment) else {
349	              continue
350	            }
351	            if active.contains(workspace) ||
352	              !@fs.exists(workspace + "/enabled") ||
353	              !@fs.exists(workspace + "/state.json") {
354	              continue
355	            }
356	            if requested {
357	              @fs.remove(workspace + "/request")
358	            }
359	            active.set(workspace, true)
360	            diagnostic_workspace_environments.set(workspace, environment)
361	            group.spawn_bg(no_wait=true, async fn() {
362	              defer {
363	                active.remove(workspace)
364	                diagnostic_workspace_environments.remove(workspace)
365	              }
366	              try {
367	                save_diagnostic(
368	                  "supervisor-workspace",
369	                  "started",
370	                  tunnel_directory=workspace,
371	                  recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
372	                    Some("0"),
373	                )
374	                if !worker_alive(workspace) {
375	                  tunnel_status(
376	                    workspace,
377	                    "connecting",
378	                    recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
379	                      Some("0"),
380	                  )
381	                  git_relay_status(
382	                    workspace,
383	                    "pending",
384	                    recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
385	                      Some("0"),
386	                  )
387	                }
388	                tunnel_worker(workspace, environment)
389	                save_diagnostic(
390	                  "supervisor-workspace",
391	                  "stopped",
392	                  tunnel_directory=workspace,
393	                  recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
394	                    Some("0"),
395	                )
396	              } catch {
397	                error => {
398	                  save_diagnostic(
399	                    "supervisor-workspace",
400	                    "failed",
401	                    tunnel_directory=workspace,
402	                    error_type="workspace_task_failed",
403	                    error_message=diagnostic_error(error, environment~),
404	                    recording=environment.get("ORCA_ENV_DEVSY_RECORDING") !=
405	                      Some("0"),
406	                  )
407	                  @async.sleep(1000)
408	                }
409	              }
410	            })
411	          } catch {
412	            error =>
413	              save_diagnostic(
414	                "supervisor-workspace",
415	                "failed",
416	                tunnel_directory=workspace,
417	                error_type="workspace_registration_failed",
418	                error_message=diagnostic_error(error),
419	              )
420	          }
421	        }
422	      }
423	      let base = directory + "/transports"
424	      if @fs.exists(base) {
425	        for name in @fs.readdir(base) {
426	          let transport = base + "/" + name
427	          if transports.contains(transport) ||
428	            !@fs.exists(transport + "/state.json") ||
429	            @fs.exists(transport + "/done") {
430	            continue
431	          }
432	          transports.set(transport, true)
433	          group.spawn_bg(no_wait=true, async fn() {
434	            defer transports.remove(transport)
435	            supervise_transport(transport) catch {
436	              error =>
437	                save_diagnostic(
438	                  "supervisor-transport",
439	                  "failed",
440	                  error_type="transport_cleanup_failed",
441	                  error_message=diagnostic_error(error),
442	                )
443	            }
444	          })
445	        }
446	      }
447	      if !active.is_empty() || !transports.is_empty() || registrations.val > 0 {
448	        idle_since = @env.now()
449	      } else if @env.now() - idle_since >= 1000 {
450	        let startup = @fs.open(
451	          directory + "/supervisor-startup.lock",
452	          mode=ReadWrite,
453	          create_mode=OpenOrCreate,
454	          permission=0o600,
455	        )
456	        let mut retained = false
457	        defer (if !retained { startup.close() })
458	        if startup.try_lock(Exclusive) &&
459	          !supervisor_pending(directory, environments) {
460	          listener.close()
461	          @fs.remove(directory + "/supervisor.json")
462	          @fs.remove(directory + "/supervisor.pid")
463	          released = true
464	          startup_hold.val = Some(startup)
465	          retained = true
466	          return
467	        }
468	      }
469	      @async.sleep(100)
470	    }
471	  })
472	}
