 372	async fn workspace_program(state : Json, program : String) -> String {
 373	  let cwd = workspace_directory(state).unwrap_or(
 374	    @env.current_dir().unwrap_or("/"),
 375	  )
 376	  if program.has_prefix("/") {
 377	    return program
 378	  }
 379	  if program.contains("/") {
 380	    return cwd + "/" + program
 381	  }
 382	  let path = field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH")
 383	  let path = match path {
 384	    Some(Json::String(value)) => value
 385	    _ => "/usr/bin:/bin"
 386	  }
 387	  let mut fallback = None
 388	  for directory in path.split(":") {
 389	    let directory = if directory.has_prefix("/") {
 390	      directory.to_owned()
 391	    } else {
 392	      cwd + "/" + directory.to_owned()
 393	    }
 394	    let candidate = directory + "/" + program
 395	    if fallback is None {
 396	      fallback = Some(candidate)
 397	    }
 398	    if transport_access(@utf8.encode(candidate + "\u0000"), 1) == 0 &&
 399	      @fs.kind(candidate) != @fs.FileKind::Directory {
 400	      return candidate
 401	    }
 402	  }
 403	  fallback.unwrap_or(cwd + "/" + program)
 404	}
