430	  let length = if size > 262144L { 262144 } else { size.to_int() }
431	  let bytes = FixedArray::make(length, b'\x00')
432	  let read = file.read_at(bytes, position=size - length.to_int64())
433	  let text = @utf8.decode_lossy(bytes.unsafe_reinterpret_as_bytes()[:read])
434	  let lines = text.split("\n").to_array()
435	  let kept = FixedArray::make(lines.length(), false)
436	  let mut remaining = 65536
437	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
438	    if i == 0 && size > length.to_int64() {
439	      continue
440	    }
441	    let event = @json.parse(lines[i].to_owned()) catch { _ => Json::null() }
442	    let overhead = if field(event, "runId") is Some(Json::String(_)) {
443	      100
444	    } else {
445	      0
446	    }
447	    let length = lines[i].length() + 1 + overhead
448	    if length <= remaining {
449	      kept[i] = true
450	      remaining -= length
451	    }
452	  }
453	  remaining = 65536
454	  for i = lines.length() - 2; i >= 0 && remaining > 0; i = i - 1 {
455	    if kept[i] || (i == 0 && size > length.to_int64()) {
